:root{
  --bg: oklch(0.985 0.015 95);
  --surface: oklch(0.995 0.01 95);
  --text: oklch(0.18 0.02 135);
  --muted: oklch(0.52 0.03 140);
  --border: oklch(0.90 0.02 120);

  --brand: oklch(0.55 0.16 155); /* ~ #00824A */
  --brand-2: oklch(0.35 0.07 145); /* forest */
  --cream: oklch(0.90 0.06 75); /* warm cream */
  --coffee: oklch(0.33 0.06 55);

  --danger: oklch(0.58 0.18 25);

  --radius-sm: 0.75rem;
  --radius: 1rem;
  --shadow-sm: 0 1px 2px oklch(0.2 0.02 140 / 0.08);
  --shadow: 0 10px 30px oklch(0.2 0.02 140 / 0.10);

  --container: 1120px;
  --font-sans: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
  --font-display: "Fraunces", ui-serif, Georgia, serif;
}

*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;
  font-family:var(--font-sans);
  color:var(--text);
  background:
    radial-gradient(1200px 600px at 20% -10%, oklch(0.90 0.08 150 / 0.35), transparent 55%),
    radial-gradient(900px 500px at 100% 0%, oklch(0.92 0.06 75 / 0.30), transparent 55%),
    var(--bg);
}
img{max-width:100%;height:auto;display:block}
a{color:inherit}

.container{max-width:var(--container);margin:0 auto;padding:0 1rem}

/* Utility */
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:.5rem;
  padding:.8rem 1.05rem;
  border-radius:999px;
  border:1px solid var(--border);
  background:var(--surface);
  box-shadow:var(--shadow-sm);
  text-decoration:none;
  font-weight:650;
  letter-spacing:-0.01em;
  transition:transform 150ms ease, box-shadow 200ms ease, background 200ms ease, border-color 200ms ease;
  cursor:pointer;
}
.btn:hover{transform:translateY(-1px);box-shadow:0 14px 30px oklch(0.2 0.02 140 / .12)}
.btn:active{transform:translateY(0px) scale(0.99)}
.btn:focus-visible{outline:3px solid oklch(0.75 0.12 160 / 0.45);outline-offset:2px}
.btn-primary{background:linear-gradient(180deg, oklch(0.60 0.16 155), oklch(0.52 0.16 155));border-color:oklch(0.50 0.14 155);color:white}
.btn-primary:hover{background:linear-gradient(180deg, oklch(0.62 0.16 155), oklch(0.50 0.16 155))}
.btn-ghost{background:transparent}
.btn-ghost:hover{background:oklch(0.97 0.02 140)}
.btn-small{padding:.55rem .8rem;font-weight:600}

.badge{display:inline-flex;align-items:center;gap:.35rem;padding:.35rem .6rem;border-radius:999px;border:1px solid var(--border);background:oklch(0.98 0.02 140);color:var(--brand-2);font-weight:650;font-size:.82rem}

.card{
  background:linear-gradient(180deg, var(--surface), oklch(0.985 0.01 95));
  border:1px solid var(--border);
  border-radius:var(--radius);
  box-shadow:var(--shadow-sm);
  overflow:hidden;
}
.card.pad{padding:1.15rem}

.kicker{color:var(--muted);font-weight:650;letter-spacing:.02em;text-transform:uppercase;font-size:.78rem}
.h1{font-family:var(--font-display);font-size:clamp(2.2rem, 4vw, 3.3rem);line-height:1.05;letter-spacing:-0.03em;margin:.5rem 0 0}
.h2{font-family:var(--font-display);font-size:clamp(1.6rem, 2.6vw, 2.2rem);line-height:1.15;letter-spacing:-0.02em;margin:0}
.lead{font-size:1.05rem;line-height:1.6;color:oklch(0.30 0.02 140)}

/* Header */
.site-header{
  position:sticky;top:0;z-index:30;
  backdrop-filter:saturate(140%) blur(10px);
  background:oklch(0.985 0.015 95 / 0.75);
  border-bottom:1px solid oklch(0.90 0.02 120 / 0.8);
}
.header-inner{display:flex;align-items:center;justify-content:space-between;padding:.85rem 0;gap:1rem}
.brand{
  display:flex;align-items:center;gap:.7rem;text-decoration:none;
}
.logo{
  width:40px;height:40px;border-radius:12px;
  background:radial-gradient(circle at 30% 20%, oklch(0.78 0.14 155), oklch(0.52 0.16 155));
  box-shadow:0 10px 22px oklch(0.2 0.02 140 / .12);
  position:relative;
}
.logo:after{content:"";position:absolute;inset:9px 10px 10px 9px;border-radius:10px;background:linear-gradient(180deg, oklch(0.96 0.05 85), transparent 70%);opacity:.55}
.brand-name{display:flex;flex-direction:column;line-height:1}
.brand-name strong{font-weight:800;letter-spacing:-0.02em}
.brand-name span{color:var(--muted);font-size:.86rem}

.nav{display:flex;align-items:center;gap:.25rem}
.nav a{padding:.55rem .75rem;border-radius:999px;text-decoration:none;color:oklch(0.26 0.02 140);font-weight:650;transition:background 200ms ease,color 200ms ease}
.nav a:hover{background:oklch(0.97 0.02 140)}
.nav a[aria-current="page"]{background:oklch(0.92 0.06 75 / .55);color:var(--brand-2)}

.header-actions{display:flex;align-items:center;gap:.5rem}

.mobile-toggle{display:none}

@media (max-width: 900px){
  .nav{display:none}
  .mobile-toggle{display:inline-flex}
  .mobile-drawer{
    display:none;
    padding:0 0 1rem;
  }
  .mobile-drawer.open{display:block}
  .mobile-drawer a{display:flex;justify-content:space-between;align-items:center;padding:.8rem .2rem;text-decoration:none;border-bottom:1px solid var(--border);color:oklch(0.24 0.02 140);font-weight:700}
}

/* Sections */
.section{padding:2.25rem 0}
.section.tight{padding:1.5rem 0}
.grid{display:grid;gap:1.1rem}
.grid.two{grid-template-columns:repeat(2,minmax(0,1fr))}
.grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}
@media (max-width: 920px){.grid.two,.grid.three{grid-template-columns:1fr}}

.hero{
  padding:2.25rem 0 1.25rem;
}
.hero-inner{
  display:grid;grid-template-columns:1.2fr .8fr;gap:1.25rem;align-items:stretch;
}
@media (max-width: 980px){.hero-inner{grid-template-columns:1fr}}

.hero-card{
  border-radius:calc(var(--radius) + .25rem);
  padding:1.5rem;
  background:
    radial-gradient(900px 500px at 0% 0%, oklch(0.82 0.12 155 / .25), transparent 55%),
    radial-gradient(700px 400px at 100% 20%, oklch(0.92 0.06 75 / .35), transparent 60%),
    linear-gradient(180deg, var(--surface), oklch(0.985 0.01 95));
  border:1px solid var(--border);
  box-shadow:var(--shadow);
  overflow:hidden;
  position:relative;
}
.hero-card:before{
  content:"";
  position:absolute;inset:-1px;
  background:
    radial-gradient(600px 280px at 20% 10%, oklch(0.60 0.16 155 / .18), transparent 60%),
    radial-gradient(500px 240px at 90% 10%, oklch(0.90 0.08 75 / .20), transparent 60%);
  pointer-events:none;
}
.hero-content{position:relative}
.hero-actions{display:flex;gap:.6rem;flex-wrap:wrap;margin-top:1rem}

.photo{
  border-radius:var(--radius);
  border:1px solid var(--border);
  overflow:hidden;
  background:oklch(0.96 0.02 95);
  box-shadow:var(--shadow-sm);
  min-height:260px;
}
.photo img{width:100%;height:100%;object-fit:cover}

.feature-row{display:flex;gap:.7rem;align-items:center;flex-wrap:wrap;margin-top:1rem}
.feature-pill{display:inline-flex;align-items:center;gap:.5rem;padding:.5rem .7rem;border-radius:999px;background:oklch(0.97 0.02 140);border:1px solid var(--border);color:oklch(0.26 0.02 140);font-weight:650;font-size:.9rem}

/* Menu */
.breadcrumb{display:flex;gap:.5rem;align-items:center;color:var(--muted);font-weight:650;font-size:.92rem}
.breadcrumb a{text-decoration:none}
.breadcrumb a:hover{text-decoration:underline}

.menu-layout{display:grid;grid-template-columns:320px 1fr;gap:1.25rem;align-items:start}
@media (max-width: 980px){.menu-layout{grid-template-columns:1fr}}

.sidebar{position:sticky;top:92px}
@media (max-width: 980px){.sidebar{position:relative;top:auto}}

.sidebar .group-title{margin:1rem 0 .6rem;color:var(--muted);font-weight:800;font-size:.82rem;text-transform:uppercase;letter-spacing:.04em}
.sidebar a{display:flex;justify-content:space-between;align-items:center;text-decoration:none;padding:.65rem .75rem;border-radius:.9rem;color:oklch(0.24 0.02 140);font-weight:650;border:1px solid transparent}
.sidebar a:hover{background:oklch(0.97 0.02 140);border-color:oklch(0.92 0.02 120)}
.sidebar a.active{background:oklch(0.92 0.06 75 / .55);border-color:oklch(0.86 0.05 75)}
.sidebar a span{color:var(--muted);font-weight:750}

.menu-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}
@media (max-width: 980px){.menu-cards{grid-template-columns:1fr}}

.item{display:flex;gap:.9rem;align-items:center}
.item .thumb{width:64px;height:64px;border-radius:14px;border:1px solid var(--border);overflow:hidden;background:oklch(0.96 0.02 95)}
.item .thumb img{width:100%;height:100%;object-fit:cover}
.item strong{display:block}
.item small{display:block;color:var(--muted);margin-top:.15rem}

/* Rewards tabs */
.tabs{display:flex;gap:.5rem;flex-wrap:wrap}
.tab{
  padding:.6rem .85rem;border-radius:999px;border:1px solid var(--border);
  background:var(--surface);
  font-weight:800;color:oklch(0.24 0.02 140);
  cursor:pointer;
  transition:background 200ms ease, transform 150ms ease, border-color 200ms ease;
}
.tab:hover{transform:translateY(-1px);background:oklch(0.97 0.02 140)}
.tab[aria-selected="true"]{background:linear-gradient(180deg, oklch(0.92 0.06 75 / .7), oklch(0.96 0.03 90));border-color:oklch(0.86 0.05 75);color:var(--brand-2)}

.tabpanel{margin-top:1rem;animation:fadeUp 350ms ease both}
@keyframes fadeUp{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}

/* Carousels */
.carousel{position:relative}
.carousel-viewport{overflow:hidden;border-radius:var(--radius);border:1px solid var(--border);background:var(--surface);box-shadow:var(--shadow-sm)}
.carousel-track{display:flex;gap:1rem;padding:1rem;transform:translateX(0);transition:transform 350ms ease}

.gift-card{
  flex:0 0 220px;
  border-radius:18px;
  border:1px solid oklch(0.88 0.03 120);
  overflow:hidden;
  background:linear-gradient(180deg, oklch(0.98 0.02 95), oklch(0.96 0.04 85));
  box-shadow:0 10px 26px oklch(0.2 0.02 140 / 0.10);
}
.gift-card .art{height:140px;background:radial-gradient(circle at 30% 20%, oklch(0.70 0.12 155), oklch(0.42 0.10 145));position:relative}
.gift-card .art:after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 70% 40%, oklch(0.92 0.06 75 / .65), transparent 55%)}
.gift-card .meta{padding:.85rem .9rem}
.gift-card .meta strong{display:block}
.gift-card .meta small{color:var(--muted)}

.carousel-btn{
  position:absolute;top:50%;transform:translateY(-50%);
  width:42px;height:42px;border-radius:999px;border:1px solid var(--border);
  background:oklch(0.99 0.01 95 / .9);
  box-shadow:var(--shadow-sm);
  display:grid;place-items:center;
  cursor:pointer;
  transition:transform 150ms ease, background 200ms ease;
}
.carousel-btn:hover{transform:translateY(-50%) scale(1.03);background:oklch(0.97 0.02 140)}
.carousel-btn:active{transform:translateY(-50%) scale(0.98)}
.carousel-btn.prev{left:-10px}
.carousel-btn.next{right:-10px}
.carousel-btn[disabled]{opacity:.45;cursor:not-allowed}

@media (max-width: 520px){
  .gift-card{flex-basis:78vw}
  .carousel-btn.prev{left:6px}
  .carousel-btn.next{right:6px}
}

/* Store locator */
.split{display:grid;grid-template-columns:1.05fr .95fr;gap:1.25rem;align-items:start}
@media (max-width: 980px){.split{grid-template-columns:1fr}}

.input{display:flex;flex-direction:column;gap:.4rem}
label{font-weight:750;color:oklch(0.24 0.02 140)}
input[type="text"], select{
  padding:.85rem .9rem;border-radius:.95rem;border:1px solid var(--border);background:var(--surface);
  box-shadow:var(--shadow-sm);
  font-size:1rem;
}
input[type="text"]:focus, select:focus{outline:3px solid oklch(0.75 0.12 160 / 0.35);border-color:oklch(0.70 0.10 160)}

.suggestions{margin-top:.4rem;border:1px solid var(--border);border-radius:.95rem;background:var(--surface);overflow:hidden;box-shadow:var(--shadow-sm);display:none}
.suggestions.open{display:block}
.suggestions button{width:100%;text-align:left;padding:.75rem .9rem;border:0;background:transparent;cursor:pointer;font-weight:650}
.suggestions button:hover{background:oklch(0.97 0.02 140)}

.pill-toggle{display:flex;gap:.5rem;flex-wrap:wrap}
.pill-toggle button{border-radius:999px;padding:.6rem .85rem;border:1px solid var(--border);background:var(--surface);font-weight:800;cursor:pointer}
.pill-toggle button[aria-pressed="true"]{background:linear-gradient(180deg, oklch(0.92 0.06 75 / .7), oklch(0.96 0.03 90));border-color:oklch(0.86 0.05 75);color:var(--brand-2)}

.map{
  height:420px;
  border-radius:var(--radius);
  border:1px solid var(--border);
  overflow:hidden;
  background:
    radial-gradient(circle at 20% 30%, oklch(0.82 0.12 155 / .18), transparent 55%),
    radial-gradient(circle at 80% 40%, oklch(0.92 0.06 75 / .25), transparent 55%),
    linear-gradient(180deg, oklch(0.98 0.01 95), oklch(0.96 0.02 95));
  position:relative;
}
.map .pin{position:absolute;width:14px;height:14px;border-radius:999px;background:var(--brand);box-shadow:0 10px 20px oklch(0.2 0.02 140 / .18)}
.map .pin:after{content:"";position:absolute;inset:-5px;border-radius:999px;border:2px solid oklch(0.55 0.16 155 / .35)}

.result{display:flex;flex-direction:column;gap:.35rem;padding:1rem;border-radius:var(--radius-sm);border:1px solid var(--border);background:var(--surface)}
.result strong{display:flex;align-items:center;justify-content:space-between;gap:.6rem}
.result small{color:var(--muted)}
.tags{display:flex;gap:.4rem;flex-wrap:wrap;margin-top:.2rem}
.tag{font-size:.78rem;font-weight:750;border-radius:999px;padding:.28rem .55rem;border:1px solid var(--border);background:oklch(0.97 0.02 140);color:oklch(0.26 0.02 140)}

.panel{display:none;margin-top:.8rem}
.panel.open{display:block}

/* Footer */
.footer{padding:2.25rem 0 2.6rem;border-top:1px solid var(--border);background:linear-gradient(180deg, transparent, oklch(0.98 0.01 95))}
.footer-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:1rem}
@media (max-width: 980px){.footer-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width: 620px){.footer-grid{grid-template-columns:1fr}}

.footer-col h3{margin:.15rem 0 .45rem;font-size:1rem}
.footer-col a{display:block;color:var(--muted);text-decoration:none;padding:.28rem 0}
.footer-col a:hover{color:oklch(0.30 0.02 140);text-decoration:underline}

.footer-meta{display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap;margin-top:1.25rem;color:var(--muted);font-size:.92rem}

/* Mobile accordion behavior */
.footer-col button.footer-acc{
  all:unset;
  display:none;
}

@media (max-width: 620px){
  .footer-col{border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);box-shadow:var(--shadow-sm);overflow:hidden}
  .footer-col h3{display:none}
  .footer-col button.footer-acc{
    display:flex;align-items:center;justify-content:space-between;
    width:100%;padding:1rem;
    cursor:pointer;font-weight:850
  }
  .footer-col .links{display:none;padding:0 1rem 1rem}
  .footer-col[aria-expanded="true"] .links{display:block;animation:fadeUp 250ms ease both}
}

/* Cookie banner */
.cookie{
  position:fixed;left:1rem;right:1rem;bottom:1rem;z-index:60;
  max-width:980px;margin:0 auto;
  border-radius:1.2rem;
  border:1px solid var(--border);
  background:oklch(0.99 0.01 95 / .95);
  box-shadow:0 20px 50px oklch(0.2 0.02 140 / .18);
  padding:1rem;
}
.cookie .row{display:flex;gap:1rem;align-items:flex-start;justify-content:space-between;flex-wrap:wrap}
.cookie p{margin:.35rem 0 0;color:var(--muted);line-height:1.5}
.cookie .actions{display:flex;gap:.5rem;flex-wrap:wrap}

/* Page heading */
.page-hero{padding:1.75rem 0 1.25rem}
.page-hero .card{padding:1.2rem}

.divider{height:1px;background:var(--border);margin:1rem 0}

.notice{border-radius:var(--radius);border:1px dashed oklch(0.80 0.05 140);background:oklch(0.97 0.02 140);padding:1rem;color:oklch(0.26 0.02 140)}

